void construct_sequence(int n, long long left[], long long right[], long long ans[]) {
    long long current = 0;
    for (int i = 0; i < n; i++) {
        ans[i] = left[i];
        current += left[i];
    }
    int idx = 0;
    while (current < 0 && idx < n) {
        long long need = -current;
        long long avail = right[idx] - left[idx];
        long long use = (avail < need) ? avail : need;
        ans[idx] += use;
        current += use;
        idx++;
    }
}

